create extension if not exists pgcrypto;
create table if not exists public.explorer_access(explorer_id text primary key,pin_hash text not null,updated_at timestamptz not null default now());
create table if not exists public.parent_access(access_id text primary key default 'family',pin_hash text not null,updated_at timestamptz not null default now());
insert into public.explorer_access(explorer_id,pin_hash) values ('jacob',crypt('1234',gen_salt('bf'))),('caitlin',crypt('1234',gen_salt('bf'))),('esmae',crypt('1234',gen_salt('bf'))),('jess',crypt('1234',gen_salt('bf'))),('chris',crypt('1234',gen_salt('bf'))),('grandad',crypt('1234',gen_salt('bf'))) on conflict(explorer_id) do nothing;
insert into public.parent_access(access_id,pin_hash) values('family',crypt('2468',gen_salt('bf'))) on conflict(access_id) do nothing;
alter table public.explorer_access enable row level security; alter table public.parent_access enable row level security;
create or replace function public.verify_explorer_pin(explorer_id text,entered_pin text) returns boolean language sql security definer set search_path=public as $$select exists(select 1 from public.explorer_access where explorer_access.explorer_id=verify_explorer_pin.explorer_id and pin_hash=crypt(entered_pin,pin_hash));$$;
create or replace function public.verify_parent_pin(entered_pin text) returns boolean language sql security definer set search_path=public as $$select exists(select 1 from public.parent_access where access_id='family' and pin_hash=crypt(entered_pin,pin_hash));$$;
create table if not exists public.parent_sessions(session_token uuid primary key default gen_random_uuid(),expires_at timestamptz not null default now()+interval '30 minutes'); alter table public.parent_sessions enable row level security;
create or replace function public.create_parent_session(entered_pin text) returns uuid language plpgsql security definer set search_path=public as $$declare t uuid;begin if not public.verify_parent_pin(entered_pin) then return null;end if;delete from public.parent_sessions where expires_at<now();insert into public.parent_sessions default values returning session_token into t;return t;end;$$;
create or replace function public.set_explorer_pin(explorer_id text,new_pin text,parent_token uuid) returns boolean language plpgsql security definer set search_path=public as $$begin if new_pin !~ '^[0-9]{4,8}$' then return false;end if;if not exists(select 1 from public.parent_sessions where session_token=parent_token and expires_at>now()) then return false;end if;update public.explorer_access set pin_hash=crypt(new_pin,gen_salt('bf')),updated_at=now() where explorer_access.explorer_id=set_explorer_pin.explorer_id;return found;end;$$;
create or replace function public.set_parent_pin(new_pin text,parent_token uuid) returns boolean language plpgsql security definer set search_path=public as $$begin if new_pin !~ '^[0-9]{4,8}$' then return false;end if;if not exists(select 1 from public.parent_sessions where session_token=parent_token and expires_at>now()) then return false;end if;update public.parent_access set pin_hash=crypt(new_pin,gen_salt('bf')),updated_at=now() where access_id='family';delete from public.parent_sessions where session_token=parent_token;return found;end;$$;
grant execute on function public.verify_explorer_pin(text,text) to anon;grant execute on function public.verify_parent_pin(text) to anon;grant execute on function public.create_parent_session(text) to anon;grant execute on function public.set_explorer_pin(text,text,uuid) to anon;grant execute on function public.set_parent_pin(text,uuid) to anon;revoke all on table public.explorer_access from anon;revoke all on table public.parent_access from anon;revoke all on table public.parent_sessions from anon;